/* CBS ACTIONS FEED (server copy of the hub Actions board). Same rules as the hub page:
   notes() + cbsPurchNotes/cbsPolicyNotes wrappers + taskOf (+ wrappers) -> auto tasks; team items (requests, incidents,
   accidents, time off, vehicle checks) by stage(); job requirements + job tasks from cbs-job-reqs-data; in-hand notes from
   cbs_task_status. Returns only New and In progress cards. KEEP IN STEP with the hub page when board rules change. */
var H='https://old-hub.example/webhook/';var h=this.helpers;
var DATA={},JRQ=[];
/* Speed: the task list (cbs-tasks-data?all=1) is fetched at the same time as the hub data and handed to Task System as _tasks.
   Job cards come from the task list, so the requirements feed is only fetched if the task list fails (same fallback as before). */
var TP=h.httpRequest({url:H+'cbs-tasks-data?all=1',json:true,timeout:60000}).then(function(r){return r&&r.ok&&Array.isArray(r.tasks)?r.tasks:null;}).catch(function(){return null;});
try{DATA=await h.httpRequest({url:H+'cbs-admin-data',json:true,timeout:30000})||{};if(typeof DATA==='string')DATA=JSON.parse(DATA);}catch(e){return [{json:{ok:false,error:'data: '+String(e.message||e)}}];}
var TASKS=await TP;
if(!TASKS){try{var jr=await h.httpRequest({method:'POST',url:H+'cbs-job-reqs-data',body:{},json:true,timeout:45000});JRQ=(jr&&Array.isArray(jr.items))?jr.items:[];}catch(e){JRQ=[];}}
var window={};
/* ---- helpers (as in the hub) ---- */
function S(v){return v==null?'':String(v).trim();}
function today(){return new Date().toISOString().slice(0,10);}
function days(d){if(!d)return null;var x=new Date(d);if(isNaN(x))return null;return Math.round((x-new Date())/86400000);}
function dd(v){return days(v);}
function nzDate(d){if(!d)return '';var s=String(d).slice(0,10);var p=s.split('-');return p.length===3?p[2]+'/'+p[1]+'/'+p[0]:String(d);}
function nz(d){d=String(d||'').slice(0,10);var p=d.split('-');return p.length===3?p[2]+'/'+p[1]+'/'+p[0]:d;}
function iso(d){d=new Date(d);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);}
function T(){return iso(new Date());}
function num(v){var x=parseFloat(String(v==null?'':v).replace(/[^0-9.\-]/g,''));return isNaN(x)?0:x;}
function money(v){var x=parseFloat(v);return isNaN(x)?'':'\u00a3'+x.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
function nzt(v){var d=new Date(v);if(!v||isNaN(d.getTime()))return String(v||'');try{return new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(d).replace(',','');}catch(e){return d.toISOString().slice(0,16).replace('T',' ');}}
function alabel(a){return (a.name||'')+(a.serial_no?' ('+a.serial_no+')':'');}
function svcFor(a){var lb=alabel(a);return (DATA.services||[]).filter(function(s){return s.asset===lb;}).sort(function(x,y){return String(y.serviced_on||'').localeCompare(String(x.serviced_on||''));});}
window.nextSvc=function(a){var s=svcFor(a);if(s.length&&s[0].next_due)return s[0].next_due;return a.next_service||'';};var nextSvc=window.nextSvc;
function openPOs(){return (DATA.pos||[]).filter(function(p){return ['Draft','Ordered','Part received'].indexOf(p.status||'Draft')>-1;});}
function onOrder(){var M={};openPOs().forEach(function(p){var L=[],R={};try{L=JSON.parse(p.lines_json||'[]');}catch(x){}try{R=JSON.parse(p.received_json||'{}')||{};}catch(x){}
 L.forEach(function(l,i){if(!l||!l.material_id)return;var left=num(l.qty)-num(R[i]);if(left<=0)return;(M[l.material_id]=M[l.material_id]||[]).push({po:p,qty:left});});});return M;}
var OO=onOrder();window.cbsOnOrder=function(id){return !!OO[id];};
/* ---- H&S policy notes ---- */
(function(){function D0(){return (DATA.hspolicy||[]);}
 function dleft(v){v=String(v||'').slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return null;return Math.round((new Date(v+'T00:00:00')-new Date(today()+'T00:00:00'))/864e5);}
 function cur(){var L=D0().filter(function(p){return p.status==='Current'&&p.approved_by&&p.approved_on;});L.sort(function(a,b){return String(b.effective_on||'').localeCompare(String(a.effective_on||''))||(b.id-a.id);});return L[0]||null;}
 window.cbsPolicyNotes=function(o){var c=cur();
  if(!c){var dr=D0().filter(function(p){return p.status!=='Superseded';}).sort(function(a,b){return b.id-a.id;})[0];o.push({s:'Health and safety',t:'hspolicy',id:dr?dr.id:0,bad:1,x:dr?'H&S policy '+(dr.version||'')+' needs Director approval':'No current H&S policy',y:'CPHSPs use the standard wording until a policy is approved'});}
  else{var d=dleft(c.review_due);if(d!==null&&d<=30)o.push({s:'Health and safety',t:'hspolicy',id:c.id,bad:d<0?1:0,x:d<0?'H&S policy review overdue':'H&S policy review due',y:'Version '+(c.version||'')+', due '+nzDate(c.review_due)});
   if(D0().filter(function(p){return p.status==='Current';}).length>1)o.push({s:'Health and safety',t:'hspolicy',id:0,bad:0,x:'More than one H&S policy marked Current',y:'Set the older versions to Superseded'});}};})();
/* ---- purchasing / contractors / load-up / sign-on / notification notes (wrapper chain, same order as the hub) ---- */
window.cbsPurchNotes=function(o){(DATA.pos||[]).forEach(function(r){var s=r.status||'';if((s==='Ordered'||s==='Part received')&&r.needed_by&&String(r.needed_by).slice(0,10)<today())o.push({s:'Purchasing',t:'pos',id:r.id,bad:0,x:(r.po_no||'PO')+' overdue from '+(r.supplier||'supplier'),y:'Needed '+nzDate(r.needed_by)+(s==='Part received'?' | part received':'')+(r.job_no?' | job '+r.job_no:'')});if(r.po_type==='Plant'&&r.hire_end&&!r.offhired_on&&s!=='Cancelled'){var hd=String(r.hire_end).slice(0,10),lim=new Date();lim.setMinutes(lim.getMinutes()-lim.getTimezoneOffset());lim.setDate(lim.getDate()+2);if(hd<=lim.toISOString().slice(0,10))o.push({s:'Purchasing',t:'pos',id:r.id,bad:0,x:'Off-hire '+(hd<today()?'overdue':'due')+': '+(r.po_no||'PO')+' from '+(r.supplier||'supplier'),y:'Off-hire '+nzDate(r.hire_end)+(r.job_no?' | job '+r.job_no:'')});}});};
(function(){var _pn=window.cbsPurchNotes;window.cbsPurchNotes=function(o){try{if(_pn)_pn(o);}catch(x){}var t=T();
 (DATA.pos||[]).forEach(function(p){if((p.status||'Draft')==='Draft')o.push({s:'Purchasing',t:'pos',id:p.id,bad:0,x:'Issue PO '+(p.po_no||'')+(p.supplier?' - '+p.supplier:''),y:[money(p.total),p.job_no?'job '+p.job_no:'stock order'].filter(Boolean).join(' | ')});});
 (DATA.subjobs||[]).forEach(function(r){var st=r.status||'Requested',dt=r.doc_type||'RAMS',co=r.company||'subcontractor',job=r.job_no?' - job '+r.job_no:'';
  var x=st==='Received'?'Review '+dt+' - '+co+job:st==='Reviewed'?'Approve '+dt+' - '+co+job:st==='Rejected - resubmit'?'Chase resubmitted '+dt+' - '+co+job:'';
  if(x)o.push({s:'Contractors',t:'subjobs',id:r.id,bad:0,x:x,y:st+(r.start_date?' | on site '+nz(r.start_date):'')});});
 (DATA.ptmsheets||[]).forEach(function(s){var sd=String(s.sheet_date||'').slice(0,10),job=s.job_no?'job '+s.job_no:(s.site||'sheet');
  if(s.status==='Issued'&&(!sd||sd>=t))o.push({s:'Plant and tools',t:'ptmsheets',id:s.id,bad:0,x:'Send load-up sheet to crew - '+job,y:[sd?'for '+nz(sd):'',s.site||''].filter(Boolean).join(' | ')});
  if(s.status==='Ready to load'&&sd&&sd<t)o.push({s:'Plant and tools',t:'ptmsheets',id:s.id,bad:0,x:'Not marked loaded - '+job,y:(s.site||'')+' | '+sd});});};})();
(function(){var _pn=window.cbsPurchNotes;window.cbsPurchNotes=function(o){try{if(_pn)_pn(o);}catch(x){}try{
 function lc(s){return String(s==null?'':s).trim().toLowerCase();}
 var A={},M={};(DATA.assets||[]).forEach(function(a){A[lc(a.name)]=1;});(DATA.materials||[]).forEach(function(m){M[lc(m.name)]=1;});
 (DATA.ptmsheets||[]).forEach(function(s){var Sx={};try{Sx=JSON.parse(s.items_json||'{}');}catch(e){}
  var L=(Sx.custom||[]).filter(function(c){var n=lc(c&&c.name);return n&&!c.reviewed&&!(c.kind==='mat'?M:A)[n];});if(!L.length)return;
  var job=s.job_no?'job '+s.job_no:(s.site||'sheet');
  o.push({s:'Plant and tools',t:'ptmsheets',id:s.id,bad:0,x:'Review custom items - '+job,y:L.slice(0,3).map(function(c){return String(c.name).trim()+(c.kind==='mat'?' (material)':'');}).join(', ')+(L.length>3?' (+'+(L.length-3)+' more)':'')});});
 }catch(e){}};})();
(function(){var _pn=window.cbsPurchNotes;window.cbsPurchNotes=function(o){try{if(_pn)_pn(o);}catch(x){}(DATA.signons||[]).forEach(function(r){if(String(r.reviewed)==='Yes')return;o.push({s:'Health and safety',t:'signons',id:r.id,bad:0,x:(r.name||'Someone')+' signed '+(r.doc_label||'a document')+' rev '+(r.doc_rev||'0'),y:[r.company,nzt(r.signed_at),r.job_no?'job '+r.job_no:''].filter(Boolean).join(' | ')});});};})();
(function(){function isOpen(r){return r&&r.id&&S(r.status)!=='Done';}function when(r){var c=S(r.created_at);return c?(nzDate(c.slice(0,10))+(c.length>10?' '+c.slice(11,16):'')):'';}
 var _pn=window.cbsPurchNotes;window.cbsPurchNotes=function(o){try{if(_pn)_pn(o);}catch(x){}(DATA.notices||[]).forEach(function(r){if(!isOpen(r))return;o.push({s:'Notifications',t:'notices',id:r.id,bad:0,x:S(r.title)||'Notification',y:[when(r),S(r.message).slice(0,140)].filter(Boolean).join(' | ')});});};})();
