(DATA.substances||[]).forEach(function(r){var d=dd(r.review_on);if(d!==null&&d<0)o.push({s:'Health and safety',t:'substances',id:r.id,bad:0,x:(r.product||'')+' review overdue',y:'SDS review'});});
(DATA.rams||[]).forEach(function(r){if(r.status==='Draft')o.push({s:'Health and safety',t:'rams',id:r.id,bad:0,x:(r.activity||'RAMS')+' still draft',y:r.site||''});});
