if(b!==null&&b<30)o.push({s:'Fleet',t:'vehicles',id:r.id,bad:b<0?1:0,x:(r.reg||'')+' MOT '+(b<0?'expired':'due in '+b+' days'),y:r.make_model||''});});
(DATA.vehicles||[]).forEach(function(r){var sd=dd(r.service_due);if(sd!==null&&sd<30)o.push({s:'Fleet',t:'vehicles',id:r.id,bad:sd<0?1:0,x:(r.reg||'')+' service '+(sd<0?'overdue':'due in '+sd+' days'),y:r.make_model||''});});
(function(){var M=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];function up(a){return String(a||'').toUpperCase().trim();}var now=new Date();var ym=now.getFullYear()+'-'+('0'+(now.getMonth()+1)).slice(-2);var fm=new Date(now.getFullYear(),now.getMonth(),1);while(fm.getDay()!==1)fm.setDate(fm.getDate()+1);var t0=new Date(now.getFullYear(),now.getMonth(),now.getDate());var since=Math.round((t0-fm)/864e5);(DATA.vehicles||[]).forEach(function(r){var R=up(r.reg);if(!R)return;if(since>=0){var done=(DATA.checks||[]).some(function(c){return up(c.vehicle)===R&&String(c.checked_on||'').slice(0,7)===ym;});if(!done)o.push({s:'Fleet',t:'vehicles',id:r.id,bad:since>7?1:0,x:R+' monthly vehicle report due',y:'Due '+fm.getDate()+' '+M[fm.getMonth()]+' | no vehicle check yet this month'});}});})();
