const ppl=t=>{const o=[];(Array.isArray(t.items)?t.items:[]).forEach(x=>{const st=S(x&&x.status);if(st==='Done'||st==='Verified')return;const a=S(x&&x.assignee);if(a&&o.indexOf(a)<0)o.push(a);});return o;};
d.items=d.items.filter(i=>i.kind!=='job');
T.forEach(t=>{const st=S(t.status);if(st==='Done'||st==='Verified')return;if(t.src==='snag'&&st==='In hand')return;
 const prog=st==='In progress'||st==='In hand',ih=st==='In hand'&&!!S(t.note);
 const job=S(t.job),due=S(t.due).slice(0,10);
 const chip=ih?[S(t.note),fd(t.note_date),S(t.note_by)].filter(Boolean).join(' \u00b7 '):'';
 const title=S(t.title)+(job?' - Job '+job:'');
 d.items.push({key:S(t.key),kind:'job',t:S(t.src)||'task',id:t.id,job:job,grp:job?'Job '+job:(S(t.category)||'Office'),type:'Job',title:title,dtitle:title,
  sub:[S(t.site).split(',')[0],due?((t.overdue?'Overdue, due ':'Due ')+dmy(due)):''].filter(Boolean).join(' \u00b7 '),urg:!!t.overdue,col:prog?'prog':'new',chip:chip,
  assignee:S(t.assignee),people:ppl(t),status:prog?'In progress':(t.overdue?'Overdue':'To do'),link:S(t.link)});});
d.counts={new:d.items.filter(i=>i.col==='new').length,prog:d.items.filter(i=>i.col==='prog').length};
return [{json:d}];

/* CLAIM KEYS (keep): an insurance claim's task is keyed on the claim itself ('claims|<id>'), not on its next-action wording, so who has it,
   its note and In progress survive when the next action is reworded. The first time, the latest saved row under an old wording-based key
   ('claims|<id>|...') is carried over. Runs before Status Tags so the card status uses it. */
const d=$input.first().json;if(!d||!d.ok||!Array.isArray(d.items))return [{json:d}];
const S=v=>v==null?'':String(v).trim();
const C=d.items.filter(i=>i&&i.t==='claims'&&i.kind==='auto');if(!C.length)return [{json:d}];
let TS=[];try{const r=await this.helpers.httpRequest({url:'https://old-hub.example/webhook/cbs-admin?a=list&t=taskstat',json:true,timeout:20000});TS=Array.isArray(r)?r:[];}catch(e){TS=[];}
const ts=r=>S(r.changed_at||r.updatedAt||r.createdAt);
C.forEach(i=>{const nk='claims|'+i.id;if(i.key===nk)return;
 const rows=TS.filter(r=>r&&(S(r.task_key)===nk||S(r.task_key).indexOf(nk+'|')===0)).sort((a,b)=>ts(b).localeCompare(ts(a)));
 const r=rows.filter(x=>S(x.task_key)===nk)[0]||rows[0];i.key=nk;
 if(r&&S(r.status)==='In progress'){i.col='prog';i.chip=[S(r.note)||'In hand',S(r.note_by)].filter(Boolean).join(' \u00b7 ');}else{i.col='new';i.chip='';}});
d.counts={new:d.items.filter(i=>i.col==='new').length,prog:d.items.filter(i=>i.col==='prog').length};
return [{json:d}];

/* CLAIM CARDS (keep, Phase 3): after Claim Keys. One task per open insurance claim, the whole time it is open (not only 7 days before its
   next action). Replaces the claim cards from Build Board. Key 'claims|<id>' (who has it, its note and In progress are kept from
   cbs_task_status). Title: the next action (or 'Update the claim'); due: the claim's next action date (i.due); urgent once overdue.
   A claim goes when it is Settled, Closed, Withdrawn or Declined. */
const d=$input.first().json;if(!d||!d.ok||!Array.isArray(d.items))return [{json:d}];
const S=v=>v==null?'':String(v).trim();const H='https://old-hub.example/webhook/';
let C=null;try{const r=await this.helpers.httpRequest({url:H+'cbs-admin-data?t=claims',json:true,timeout:30000});C=(r&&Array.isArray(r.claims))?r.claims:null;}catch(e){C=null;}
if(!C){d._claims='unavailable';return [{json:d}];}
let TS=[];try{const r=await this.helpers.httpRequest({url:H+'cbs-admin?a=list&t=taskstat',json:true,timeout:20000});TS=Array.isArray(r)?r:[];}catch(e){TS=[];}
const TSm={};TS.forEach(r=>{if(r&&r.task_key)TSm[S(r.task_key)]=r;});
const T0=new Date().toLocaleDateString('en-CA',{timeZone:'Europe/London'});
const dmy=v=>{const m=S(v).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[3]+'/'+m[2]+'/'+m[1]:'';};
const days=v=>Math.round((Date.parse(v+'T12:00:00Z')-Date.parse(T0+'T12:00:00Z'))/864e5);
const fd=v=>{v=S(v).slice(0,10);if(!/^\d{4}-\d\d-\d\d$/.test(v))return '';try{return new Date(v+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'});}catch(e){return dmy(v);}};
const CLOSED=/^(settled|closed|withdrawn|declined)$/i;
d.items=d.items.filter(i=>!(i&&i.t==='claims'&&i.kind==='auto'));
C.forEach(c=>{if(!c||!c.id||CLOSED.test(S(c.status)))return;
 const no=S(c.claim_no)||('Claim '+c.id),due=S(c.next_action_due).slice(0,10),ok=/^\d{4}-\d\d-\d\d$/.test(due),dl=ok?days(due):null;
 const what=[S(c.claim_type),S(c.vehicle)||S(c.asset)||S(c.site),S(c.insurer)].filter(Boolean).join(' \u00b7 ');
 const sub=[S(c.status)||'Open',!ok?'No next action date set':(dl<0?'Overdue: next action was due '+dmy(due):(dl===0?'Next action due today':'Next action due in '+dl+(dl===1?' day':' days')+' ('+dmy(due)+')')),what].filter(Boolean).join(' | ');
 const key='claims|'+c.id,st=TSm[key],prog=!!(st&&S(st.status)==='In progress');
 d.items.push({key,kind:'auto',t:'claims',id:c.id,grp:'Insurance',type:'Auto',title:'Claim '+no+': '+(S(c.next_action)||'Update the claim'),sub,urg:ok&&dl<0,due:ok?due:'',
  col:prog?'prog':'new',chip:prog?[S(st.note)||'In hand',fd(st.note_date),S(st.note_by)].filter(Boolean).join(' \u00b7 '):''});});
d._claims='ok';d.counts={new:d.items.filter(i=>i.col==='new').length,prog:d.items.filter(i=>i.col==='prog').length};
return [{json:d}];

/* PLANT OVERDUE BACK (keep, Ethan 28/10): one auto card per job (or per person / van when the item has no job) for plant past its
   due-back date. Overdue = due_back before today AND (out on a job OR yard_status Out). Replaces the old per-item 'Not back in the yard'
   notes (which never became cards) and the 'Plant overdue back' note that used to reopen the job's Plant & materials task.
   Key 'plantback|<group>' (who has it / note / In progress kept from cbs_task_status). items = the asset ids, for the drawer's
   Back in yard / Extend / Move buttons (CBS - Tasks 'Plant Back UI', server cbs-plant-act). */
const d=$input.first().json;if(!d||!d.ok||!Array.isArray(d.items))return [{json:d}];
const S=v=>v==null?'':String(v).trim();const H='https://old-hub.example/webhook/';
let A=null;try{const r=await this.helpers.httpRequest({url:H+'cbs-admin-data?t=assets',json:true,timeout:30000});A=(r&&Array.isArray(r.assets))?r.assets:null;}catch(e){A=null;}
if(!A){d._plant='unavailable';return [{json:d}];}
let TS=[];try{const r=await this.helpers.httpRequest({url:H+'cbs-admin?a=list&t=taskstat',json:true,timeout:20000});TS=Array.isArray(r)?r:[];}catch(e){TS=[];}
const TSm={};TS.forEach(r=>{if(r&&r.task_key)TSm[S(r.task_key)]=r;});
const T0=new Date().toLocaleDateString('en-CA',{timeZone:'Europe/London'});
const dmy=v=>{const m=S(v).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[3]+'/'+m[2]+'/'+m[1]:'';};
const fd=v=>{v=S(v).slice(0,10);if(!/^\d{4}-\d\d-\d\d$/.test(v))return '';try{return new Date(v+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'});}catch(e){return dmy(v);}};
const G={};
A.forEach(a=>{if(!a||!a.id||/^(retired|lost)$/i.test(S(a.status)))return;const due=S(a.due_back).slice(0,10);if(!/^\d{4}-\d\d-\d\d$/.test(due)||due>=T0)return;
 const job=S(a.out_job).replace(/^#/,'');if(!job&&S(a.yard_status)!=='Out')return;
 const g=job?'Job '+job:(S(a.out_with)||S(a.location)||'No job');(G[g]=G[g]||{job,ids:[],names:[],due}).ids.push(a.id);G[g].names.push(S(a.name)||'item');if(due<G[g].due)G[g].due=due;});
d.items=d.items.filter(i=>!(i&&i.t==='plantback'));
Object.keys(G).forEach(g=>{const x=G[g],n=x.ids.length,key='plantback|'+g,st=TSm[key],prog=!!(st&&S(st.status)==='In progress');
 d.items.push({key,kind:'auto',t:'plantback',id:g,job:x.job,grp:'Plant and tools',type:'Auto',title:'Plant overdue back - '+g,
  sub:n+(n===1?' item':' items')+' overdue | due back '+dmy(x.due)+' | '+x.names.slice(0,4).join(', ')+(n>4?' (+'+(n-4)+' more)':''),urg:true,due:x.due,items:x.ids,
  col:prog?'prog':'new',chip:prog?[S(st.note)||'In hand',fd(st.note_date),S(st.note_by)].filter(Boolean).join(' \u00b7 '):''});});
d._plant='ok';d.counts={new:d.items.filter(i=>i.col==='new').length,prog:d.items.filter(i=>i.col==='prog').length};
return [{json:d}];
